    response = await client.post(
        "/v1/chat/completions/derender",
        json={
            "model": MODEL_NAME,
            "generate_response": {
                "request_id": "test-logprobs-bound",
                "choices": [
                    {
                        "index": 0,
                        "token_ids": [42],
                        "finish_reason": "stop",
                        "logprobs": oversized_logprobs,
                    }
